validator:
function validate(input) {
  const [{ Sales = [], Product = [] }] = input;
  const products = new Set(), sales = new Set();
  for (const [id] of Product) {
    if (id === null) return 'Every product needs a product_id.';
    if (products.has(id)) return `product_id ${id} appears twice in Product.`;
    products.add(id);
  }
  for (const [saleId, productId, year] of Sales) {
    if (saleId === null || year === null) return 'Every sale needs a sale_id and a year.';
    const key = `${saleId}/${year}`;
    if (sales.has(key)) return `Sale ${saleId} appears twice in year ${year}.`;
    sales.add(key);
    if (!products.has(productId)) return `Sale ${saleId} names product ${productId}, which is not in Product.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Nokia', 'Apple', 'Samsung', 'LG', 'Sony', 'Xiaomi', 'Oppo', 'Nokia'];
  const productCount = small ? Math.floor(rand() * 5) : 1000;
  const Product = [];
  for (let i = 0; i < productCount; i++) Product.push([100 * (i + 1), small ? pick(names) : `P${i}`]);
  const Sales = [];
  if (productCount > 0) {
    // A few sale ids spread over a few years, so one sale_id can repeat in different years.
    const saleCount = small ? Math.floor(rand() * 9) : 2000;
    const used = new Set();
    while (Sales.length < saleCount) {
      const saleId = 1 + Math.floor(rand() * (small ? 6 : 1500)), year = 2005 + Math.floor(rand() * (small ? 4 : 20));
      if (used.has(`${saleId}/${year}`)) continue;
      used.add(`${saleId}/${year}`);
      const price = small ? pick([500, 5000, 9000, 9000]) : 100 * (1 + Math.floor(rand() * 100));
      Sales.push([saleId, pick(Product)[0], year, 1 + Math.floor(rand() * 20), price]);
    }
  }
  return [{ Sales, Product }];
}
